import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function formatCurrency(amount: number, settings?: { language: string; currencySymbol: string } | null) {
  if (amount === undefined || amount === null || isNaN(amount)) return '';

  const localeMap: Record<string, string> = {
    'en': 'en-US',
    'th': 'th-TH',
    'lo': 'lo-LA'
  };

  const lang = settings?.language || 'en';
  const locale = localeMap[lang] || 'en-US';
  const symbol = settings?.currencySymbol || '$';

  // Map symbol to currency code for Intl.NumberFormat
  // This ensures correct placement of symbol (prefix/suffix) based on locale
  const symbolToCode: Record<string, string> = {
    '$': 'USD',
    '฿': 'THB',
    '₭': 'LAK'
  };

  const currencyCode = symbolToCode[symbol];

  if (currencyCode) {
    try {
      return new Intl.NumberFormat(locale, {
        style: 'currency',
        currency: currencyCode,
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      }).format(amount);
    } catch (e) {
      // Fallback if locale/currency combo fails
    }
  }

  // Fallback manual formatting
  const numberPart = new Intl.NumberFormat(locale, {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);

  return `${symbol}${numberPart}`;
}
